import ToggleSwitch from "./ToggleSwitch";
import { Caption } from "../typography/Caption";

interface IProps {
    // The value for the toggle switch
    "value": boolean;
    // The translated label for the switch
    "label": string;
    // The translated caption for the switch
    "caption"?: string;
    // Tooltip to display
    "tooltip"?: string;
    // Whether or not to disable the toggle switch
    "disabled"?: boolean;
    // True to put the toggle in front of the label
    // Default false.
    "toggleInFront"?: boolean;
    // Additional class names to append to the switch. Optional.
    "className"?: string;
    // The function to call when the value changes
    onChange(checked: boolean): void;

    "data-testid"?: string;
}

export default class LabelledToggleSwitch extends React.PureComponent<IProps> {
    private readonly id = `mx_LabelledToggleSwitch_${randomString(12)}`;

    public render(): React.ReactNode {
        // This is a minimal version of a SettingsFlag
        const { label, caption } = this.props;
        let firstPart = (
            <span className="mx_SettingsFlag_label">
                <div id={this.id}>{label}</div>
                {caption && <Caption id={`${this.id}_caption`}>{caption}</Caption>}
            </span>
        );
        let secondPart = (
            <ToggleSwitch
                checked={this.props.value}
                disabled={this.props.disabled}
                onChange={this.props.onChange}
                tooltip={this.props.tooltip}
                aria-labelledby={this.id}
                aria-describedby={caption ? `${this.id}_caption` : undefined}
            />
        );

        if (this.props.toggleInFront) {
            [firstPart, secondPart] = [secondPart, firstPart];
        }

        const classes = classNames("mx_SettingsFlag", this.props.className, {
            mx_SettingsFlag_toggleInFront: this.props.toggleInFront,
        });
        return (
            <div data-testid={this.props["data-testid"]} className={classes}>
                {firstPart}
                {secondPart}
            </div>
        );
    }
}

}

/**
 * Query the server to see if it lists support for an unstable feature
 * in the /versions response
 * @param feature - the feature name
 * @returns true if the feature is supported
 */
public async doesServerSupportUnstableFeature(feature: string): Promise<boolean> {
    const response = await this.getVersions();
    if (!response) return false;
    const unstableFeatures = response["unstable_features"];
    return unstableFeatures && !!unstableFeatures[feature];
}

/**
 * Query the server to see if it is forcing encryption to be enabled for
 * a given room preset, based on the /versions response.
 * @param presetName - The name of the preset to check.
 * @returns true if the server is forcing encryption
 * for the preset.
 */
public async doesServerForceEncryptionForPreset(presetName: Preset): Promise<boolean> {
    const response = await this.getVersions();
    if (!response) return false;
    const unstableFeatures = response["unstable_features"];

    // The preset name in the versions response will be without the _chat suffix.
    const versionsPresetName = presetName.includes("_chat")
        ? presetName.substring(0, presetName.indexOf("_chat"))
        : presetName;

    return unstableFeatures && !!unstableFeatures[`io.element.e2ee_forced.${versionsPresetName}`];
}

